span.wschewtoy__pi{opacity:1;width:58px;height:58px;border-radius:50%;background:#c1e2ce;border:1px solid #2f9e5b;color:#27844c;display:flex;align-items:center;justify-content:center;margin:0 auto 14px}.wschewtoy__pi svg{width:28px;height:28px}
