.wschewtoy__ime{display:flex;align-items:center;gap:10px}.wschewtoy__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#c1e2ce;border:1px solid #2f9e5b;color:#27844c;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
